import {cached,saveCache,clearCache,syncQueue,pending} from './offline.mjs';
import {premiumNav,premiumDashboard,premiumMobile,bindPremium,openPremium,premiumView} from './premium.mjs';
import {extraView,extraForm,replenishment,pathName} from './workspace.mjs';import {icon} from './icons.mjs';
import {prefs,persist,t,esc,n,date,name,$,toast,btn,tag,table,panel,show,close,api,download,csv,chooseFile,parseCSV,errorText,field,applyTheme,currency,unit} from './ui.mjs';
import {available,roles,authorize} from './core.mjs';import {openForm} from './forms.mjs';
let state,me,meta={},page=location.hash.slice(1)||'dashboard',filter={search:'',warehouse:'',from:'',to:'',report:'summary',index:0},connected=true,notificationIds=new Set();
const icons={dashboard:'◫',products:'◇',categories:'≡',brands:'◈',units:'⌗',pricing:'¤',inventory:'▤',warehouses:'▱',transfers:'⇄',counts:'☑',purchasing:'↙',sales:'↗',contacts:'♧',tracking:'▦',reports:'▥',alerts:'♧',reminders:'◷',activity:'↺',users:'♙',integrations:'⌘',settings:'⚙',mobile:'▯',help:'?'};
const pget=id=>state.products.find(p=>p.id===id),wget=id=>state.warehouses.find(w=>w.id===id),layerName=b=>`${name(pget(b.product))} · ${name(wget(b.warehouse))} · ${b.lot||b.serial||b.id.slice(0,6)}`;
function can(type,extra={}){try{authorize(me,{type,...extra},state);return true}catch{return false}}
const action=(label,type,arg='',extra={})=>can(type,extra)?btn(label,type,arg):'';
const productCell=p=>p?`<div class="product-cell"><span class="product-icon">${p.image?.startsWith('data:image/')?`<img src="${esc(p.image)}" alt="">`:icon(p.tracking==='serial'?'tracking':'products')}</span><div><b>${esc(name(p))}</b><small dir="ltr">${esc(p.sku)} · ${esc(unit(p.unit))}</small></div></div>`:'—';
const qty=(id,w=filter.warehouse)=>state.stock.filter(b=>b.product===id&&(!w||b.warehouse===w)).reduce((n,b)=>n+b.qty,0);
const reserved=(id,w=filter.warehouse)=>state.stock.filter(b=>b.product===id&&(!w||b.warehouse===w)).reduce((n,b)=>n+b.reserved,0);
const low=()=>[...new Map(replenishment(state,filter.warehouse).filter(x=>x.low).map(x=>[x.product.id,x.product])).values()];
function matches(p){let q=filter.search.toLowerCase();return !q||[p.name,p.en,p.sku,p.barcode].some(x=>x?.toLowerCase().includes(q))||state.stock.some(b=>b.product===p.id&&[b.lot,b.serial].some(x=>x?.toLowerCase().includes(q)))}
function slice(list){return list.slice(filter.index*50,filter.index*50+50)}
const pagination=length=>`<div class="pagination"><span>${n(Math.min(length,filter.index*50+1))}–${n(Math.min(length,(filter.index+1)*50))} / ${n(length)}</span><div>${filter.index?btn('previous','previous'):''}${(filter.index+1)*50<length?btn('next','next'):''}</div></div>`;
function toolbar(dates=false){return `<div class="toolbar"><input id="filter-search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(filter.search)}"><select id="filter-warehouse" aria-label="${t('warehouse')}"><option value="">${t('all')}</option>${state.warehouses.map(w=>`<option value="${w.id}" ${filter.warehouse===w.id?'selected':''}>${esc(name(w))}</option>`).join('')}</select>${dates?`<label>${t('startDate')} <input id="filter-from" type="date" value="${esc(filter.from)}"></label><label>${t('endDate')} <input id="filter-to" type="date" value="${esc(filter.to)}"></label>`:''}</div>`}
async function loadMeta(){meta={};if(['settings','system'].includes(page)&&me.role==='owner')meta.system=await api('system');if(page==='users'&&me.role==='owner')meta.users=await api('users');if(page==='integrations'&&me.role==='owner'){meta.keys=await api('keys');meta.users=await api('users');meta.hooks=await api('hooks')}}
async function refresh(){state=await api('state');await loadMeta();connected=true;saveCache(me,state);draw()}
async function mutate(command){command={...command,requestId:crypto.randomUUID()};let result=await api('actions',command);if(result.queued){toast(prefs.lang==='fa'?'در صف آفلاین ذخیره شد؛ هنوز روی موجودی اعمال نشده است.':'Saved to offline queue; inventory is not updated yet.');return}state=result;saveCache(me,state);await loadMeta();draw();toast(t('ok'))}
const context=()=>({state,me,meta,mutate,refresh,go,reportData,can,pget,wget,layerName,filter,lowTable,low,productCell});
async function go(p){page=p;filter.index=0;location.hash=p;await loadMeta();draw()}
function headerActions(){const a={variants:action('newProduct','product'),supplierReturns:action('supplier_return','supplier_return'),replenishment:action('ruleNew','reorder_rule'),dashboard:'',products:action('newProduct','product')+action('import','import_products')+btn('export','exportProducts'),categories:action('new','master','categories'),brands:action('new','master','brands'),units:action('new','master','units'),pricing:action('new','price'),inventory:action('receive','receive')+action('issue','issue')+action('count','count'),warehouses:action('newWarehouse','warehouse')+action('newLocation','location'),transfers:action('transfer','transfer'),counts:action('newCount','count_create'),purchasing:action('newOrder','order','purchase',{kind:'purchase'}),sales:action('newOrder','order','sales',{kind:'sales'}),contacts:action('newContact','contact'),reports:btn('saveView','saveReport')+btn('export','exportReport')+btn('print','print'),reminders:action('newReminder','reminder'),users:me.role==='owner'?btn('new','user')+btn('customRoles','custom_role'):''};return a[page]||''}
function draw(){if(!state)return;applyTheme();document.title=prefs.lang==='fa'?'ماکان استاک | مدیریت انبار و موجودی':'MAKAN STOCK | Inventory workspace';document.documentElement.dataset.mode=prefs.mode;document.documentElement.lang=prefs.lang;document.documentElement.dir=prefs.lang==='fa'?'rtl':'ltr';let pages=['dashboard','products',...(prefs.mode==='pro'?['categories','brands','units','variants','pricing']:[]),'inventory','warehouses','transfers','counts',...(prefs.mode==='pro'?['replenishment','warehouseMap','pickWave']:[]),'purchasing',...(prefs.mode==='pro'?['supplierReturns','requests','supplierAnalysis']:[]),'sales','contacts',...(prefs.mode==='pro'?['tracking']:[]),'reports','alerts','reminders',...(prefs.mode==='pro'?['automations']:[]),'mobile',...(['owner','manager'].includes(me.role)?['activity']:[]),...(me.role==='owner'?['users','integrations','system']:[]),'settings','offlineQueue','roadmap','help','about'];
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>${prefs.lang==='fa'?'ماکان استاک':'MAKAN STOCK'}<small>${prefs.lang==='fa'?'مدیریت یکپارچه موجودی':'INVENTORY, IN ORDER.'}</small></div></div><div class="workspace"><span class="avatar">${esc(me.name[0])}</span><div><b>${esc(state.settings.company)}</b>${esc(me.name)} · ${t(me.role==='warehouse'?'warehouseRole':me.role)}</div></div><nav class="nav">${premiumNav(page,pages)}</nav><footer>● ${t('footer')}<br>${t('noAccounting')}</footer></aside><main class="main"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Menu">☰</button><div class="search">${icon("search")}<input id="global-search" placeholder="${t('search')}" aria-label="${t('search')}"></div><div class="top-actions"><span id="connection" class="conn ${connected?'':'offline'}">${t(connected?'connected':'offline')}</span><button data-action="theme" aria-label="${t('toggleTheme')}" title="${t('toggleTheme')}">${icon(prefs.theme==='dark'?'sun':'moon')}</button><button data-action="lang">${prefs.lang==='fa'?'English':'فارسی'}</button><button data-action="mode">${t(prefs.mode==='simple'?'pro':'simple')}</button><button data-go="reminders">◷ ${n(state.notifications.filter(x=>!x.read).length)}</button><button data-action="logout">${t('logout')}</button></div></header><div class="content"><div class="crumb"><span>${prefs.lang==='fa'?'ماکان استاک':'MAKAN STOCK'}</span><span>›</span><span>${t(page)}</span></div><div class="heading"><div><h1>${page==='dashboard'?(prefs.lang==='fa'?'امروز در انبار شما':'Your warehouse today'):t(page)}</h1><p>${page==='dashboard'?t('subtitle'):date(new Date().toISOString())}</p></div><div class="actions">${headerActions()}</div></div><div class="workspace-status"><span>● ${t('connected')} · ${esc(state.settings.company)}</span><time id="clock"></time></div>${view()}<div class="bottom-note"><span>${t('noAccounting')} · ${prefs.lang==='fa'?'نوشته‌شده توسط ماکان':'Created by Makan'} · <a href="https://makanlab.tech/" target="_blank" rel="noopener noreferrer">MAKAN LAB</a> · MIT</span><span>${prefs.lang==='fa'?'ویندوز · نسخه ۱.۳':'Windows · 1.3'}</span></div></div></main></div>`;bindFilters();bindPremium(context(),page);clock()}
function clock(){if($('#clock'))$('#clock').textContent=new Intl.DateTimeFormat(prefs.lang==='fa'?'fa-IR':'en-GB',{timeZone:prefs.zone,hour:'2-digit',minute:'2-digit'}).format(new Date())}
function bindFilters(){for(let [id,key] of [['filter-search','search'],['filter-warehouse','warehouse'],['filter-from','from'],['filter-to','to'],['report-type','report']]){let el=$('#'+id);if(el)el.onchange=e=>{filter[key]=e.target.value;filter.index=0;draw()}}if($('#scan-input'))$('#scan-input').onkeydown=e=>{if(e.key==='Enter')scan()}}
function dashboard(){let open=state.orders.filter(o=>!['received','dispatched','returned','cancelled'].includes(o.status)).length,metrics=[['totalProducts',state.products.filter(p=>p.active).length,'◇'],['stockUnits',state.products.filter(p=>qty(p.id)>0).length,'▤'],['lowCount',low().length,'↘'],['openOrders',open,'↗']],total=state.stock.reduce((s,b)=>s+b.qty,0);
let dates=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let ms=state.movements.filter(m=>m.at.slice(0,10)===d.toISOString().slice(0,10));return {d,in:ms.reduce((s,m)=>s+Math.max(m.qty,0),0),out:ms.reduce((s,m)=>s+Math.max(-m.qty,0),0)}}),max=Math.max(1,...dates.flatMap(x=>[x.in,x.out]));
return `<div class="metrics">${metrics.map(([k,v,ic])=>`<div class="metric"><span class="symbol">${ic}</span><label>${t(k)}</label><strong>${n(v)}</strong><small>${t('today')}</small></div>`).join('')}</div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>${t('movement')}</h2><small>${t('movementHint')}</small></div><span class="tag">${n(state.movements.length)}</span></div><div class="chart">${dates.map(x=>`<div class="bars"><i style="height:${x.in/max*85}%" title="${x.in}"></i><i class="out" style="height:${x.out/max*85}%" title="${x.out}"></i><em>${date(x.d.toISOString()).split(' ').slice(0,2).join(' ')}</em></div>`).join('')}</div><div class="legend"><span>${t('inbound')}</span><span>${t('outbound')}</span></div><p class="notice">${prefs.lang==='fa'?'نمودار تعداد گردش را با واحدهای مختلف نشان می‌دهد؛ برای تحلیل مقدار از گزارش هر کالا استفاده کنید.':'Chart combines movement quantities across units; use per-product reports for quantity analysis.'}</p></section>${panel('distribution',`<div class="distribution">${state.warehouses.map(w=>{let v=state.stock.filter(b=>b.warehouse===w.id&&b.qty>0),k=new Set(v.map(b=>b.product)).size;return `<div class="warehouse-stat"><header><span>${esc(name(w))}</span><b>${n(k)} ${t('product')}</b></header><div class="progress"><i style="width:${state.products.length?k/state.products.length*100:0}%"></i></div></div>`}).join('')}<div class="insight">${t('permissionHint')}</div></div>`)}</div><div class="grid">${panel('attention',lowTable(),`<button data-go="alerts">${t('seeAll')} ↗</button>`)}${panel('recent',table(['product','qty','type','at'],state.movements.slice(0,5).map(m=>`<tr><td>${productCell(pget(m.product))}</td><td dir="ltr">${n(m.qty)}</td><td>${t(m.type)}</td><td>${date(m.at)}</td></tr>`)))}</div>`}
function lowTable(){return table(['product','warehouse','available','min','suggested','action'],replenishment(state,filter.warehouse).filter(x=>x.low).map(x=>`<tr><td>${productCell(x.product)}</td><td>${x.rule.warehouse?esc(name(wget(x.rule.warehouse))):t('all')}</td><td>${n(x.available)}</td><td>${n(x.rule.min)}</td><td>${n(x.suggest)}<small>${t('onOrder')}: ${n(x.incoming)}</small></td><td>${can('order',{kind:'purchase'})?btn('reorder','reorder',x.product.id+'|'+(x.rule.warehouse||'')+'|'+x.suggest):''}</td></tr>`))}
function filteredMovements(){return state.movements.filter(m=>(!filter.warehouse||m.warehouse===filter.warehouse)&&(!filter.from||m.at.slice(0,10)>=filter.from)&&(!filter.to||m.at.slice(0,10)<=filter.to)&&matches(pget(m.product)))}
function stockRows(list){return list.map(b=>`<tr><td>${productCell(pget(b.product))}</td><td>${esc(name(wget(b.warehouse)))}<small>${esc(pathName(state,b.location)||'—')}</small></td><td>${n(b.qty)}</td><td>${n(b.reserved)}</td><td>${tag(b.status)}${b.expiry&&b.expiry<new Date().toISOString().slice(0,10)?tag('expired'):''}</td><td>${esc(b.lot||b.serial||'—')}</td><td>${date(b.expiry)}</td><td><div class="row-actions">${btn('trace','trace',b.product+'|'+(b.serial||b.lot||''))}${can('bin_move',{layer:b.id})?btn('bin_move','bin_move',b.id):''}${b.status==='quarantine'&&can('release',{layer:b.id})?btn('release','release',b.id):''}</div></td></tr>`)}
function view(){const pv=premiumView(page,context());if(pv!==null)return pv;if(page==='dashboard')return premiumDashboard(context());if(page==='mobile')return premiumMobile(context());const added=extraView(page,context());if(added!==null)return added;switch(page){case 'dashboard':return dashboard();
case 'products':{let list=state.products.filter(matches);return panel('products',toolbar()+table(['product','category','onHand','available','price','tracking','action'],slice(list).map(p=>`<tr><td>${productCell(p)}${!p.active?tag('archive'):''}</td><td>${esc(name(state.categories.find(c=>c.id===p.category)))}</td><td>${n(qty(p.id))}</td><td>${n(available(state,p.id,filter.warehouse))}</td><td>${n(p.price)}<small>${esc(currency(p.currency))}</small></td><td>${tag(p.tracking)}<small>${t(p.policy)}</small></td><td><div class="row-actions">${btn('details','productDetail',p.id)}${action('edit','product_update',p.id)}${btn('label','label',p.id)}</div></td></tr>`))+pagination(list.length))}
case 'categories':case 'brands':case 'units':return panel(page,table(['name','en',...(page==='units'?['code']:[]),'action'],state[page].map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.en)}</td>${page==='units'?`<td>${esc(x.code)}</td>`:''}<td>${action('edit','master_update',page+'|'+x.id)}</td></tr>`)));
case 'pricing':return panel('pricing',table(['name','product','amount','currency','validFrom','validTo'],state.prices.map(x=>`<tr><td>${esc(x.name)}</td><td>${productCell(pget(x.product))}</td><td>${n(x.amount)}</td><td>${esc(currency(x.currency))}</td><td>${date(x.validFrom)}</td><td>${date(x.validTo)}</td></tr>`)));
case 'inventory':{let list=state.stock.filter(b=>b.qty>0&&matches(pget(b.product))&&(!filter.warehouse||b.warehouse===filter.warehouse));return panel('inventory',toolbar()+table(['product','warehouse','onHand','reserved','status','lot','expiry','action'],stockRows(slice(list)))+pagination(list.length))+`<br>`+panel('movement',table(['product','warehouse','qty','type','lot','at'],filteredMovements().slice(0,30).map(m=>`<tr><td>${productCell(pget(m.product))}</td><td>${esc(name(wget(m.warehouse)))}</td><td dir="ltr">${n(m.qty)}</td><td>${esc(t(m.type))}</td><td>${esc(m.lot||m.serial||'—')}</td><td>${date(m.at)}</td></tr>`)))}
case 'warehouses':return `<div class="cards">${state.warehouses.map(w=>`<article class="card"><span class="product-icon">▱</span><h3>${esc(name(w))}</h3><p>${esc(w.location)}</p><b>${n(state.stock.filter(b=>b.warehouse===w.id&&b.qty>0).length)} ${t('lot')}</b><p>${state.locations.filter(l=>l.warehouse===w.id).map(l=>`<span class="tag">${esc(name(l))}</span>`).join(' ')||'—'}</p></article>`).join('')}</div>`;
case 'transfers':return panel('transfers',table(['product','from','to','qty','receivedQty','status','action'],state.transfers.map(x=>`<tr><td>${productCell(pget(x.product))}</td><td>${esc(name(wget(x.from)))}</td><td>${esc(name(wget(x.to)))}</td><td>${n(x.qty)}</td><td>${n(x.received)}</td><td>${tag(x.status)}</td><td>${x.status!=='received'?action('confirmReceive','transfer_receive',x.id,{id:x.id}):''}</td></tr>`)));
case 'counts':return panel('counts',table(['warehouse','created','name','status','action'],state.counts.map(c=>`<tr><td>${esc(name(wget(c.warehouse)))}</td><td>${date(c.at)}</td><td>${esc(c.createdBy)}</td><td>${tag(c.status)}</td><td>${btn('details','countDetail',c.id)} ${c.status==='pending'?action('approve','count_approve',c.id,{id:c.id})+action('count_recount','count_recount',c.id,{id:c.id}):''}</td></tr>`)));
case 'purchasing':case 'sales':{let list=state.orders.filter(o=>o.kind===(page==='purchasing'?'purchase':'sales')&&(!filter.warehouse||o.warehouse===filter.warehouse)&&(!filter.search||o.number.toLowerCase().includes(filter.search.toLowerCase())||o.lines.some(l=>matches(pget(l.product)))));return panel(page,toolbar()+table(['code','contact','warehouse','lines','due','status','action'],slice(list).map(o=>`<tr><td><b>${esc(o.number)}</b><small>${date(o.at)}</small></td><td>${esc(state.contacts.find(c=>c.id===o.contact)?.name)}</td><td>${esc(name(wget(o.warehouse)))}</td><td>${n(o.lines.length)}</td><td>${date(o.due)}</td><td>${tag(o.status)}</td><td>${btn('details','orderDetail',o.id)}</td></tr>`))+pagination(list.length))}
case 'contacts':return panel('contacts',table(['name','type','email','phone','address','action'],state.contacts.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${tag(c.type)}</td><td>${esc(c.email)}</td><td dir="ltr">${esc(c.phone)}</td><td>${esc(c.address)}</td><td>${action('edit','contact_update',c.id)}</td></tr>`)));
case 'tracking':{let list=state.stock.filter(b=>b.qty>0&&(b.lot||b.serial)&&matches(pget(b.product))&&(!filter.warehouse||b.warehouse===filter.warehouse));return panel('tracking',toolbar()+table(['product','warehouse','onHand','reserved','status','lot','expiry','action'],stockRows(slice(list)))+pagination(list.length))}
case 'reports':return reports();
case 'alerts':return panel('replenish',toolbar()+lowTable())+`<br>`+panel('expiry',table(['product','warehouse','lot','qty','expiry'],state.stock.filter(b=>b.qty>0&&b.expiry&&Date.parse(b.expiry)-Date.now()<90*86400000).map(b=>`<tr><td>${productCell(pget(b.product))}</td><td>${esc(name(wget(b.warehouse)))}</td><td>${esc(b.lot||b.serial)}</td><td>${n(b.qty)}</td><td>${date(b.expiry)} ${b.expiry<new Date().toISOString().slice(0,10)?tag('expired'):''}</td></tr>`)));
case 'reminders':return panel('reminders',table(['name','due','note','status','action'],state.reminders.map(r=>`<tr><td>${esc(r.name)}</td><td>${date(r.due)} <small>${new Intl.DateTimeFormat(prefs.lang==='fa'?'fa-IR':'en',{timeZone:prefs.zone,hour:'2-digit',minute:'2-digit'}).format(new Date(r.due))}</small></td><td>${esc(r.note)}</td><td>${tag(r.done?'done':'pending')}</td><td>${!r.done?action('done','reminder_done',r.id):''}</td></tr>`)))+`<br>`+panel('notifications',table(['name','at','status','action'],state.notifications.map(x=>`<tr><td>${esc(x.name)}</td><td>${date(x.at)}</td><td>${tag(x.read?'read':'pending')}</td><td>${!x.read?action('read','notification_read',x.id):''}</td></tr>`)));
case 'activity':{let list=state.audit;return panel('activity',table(['type','name','at','reason','action'],slice(list).map(a=>`<tr><td>${esc(t(a.action))}</td><td>${esc(a.actor)}</td><td>${date(a.at)}</td><td>${esc(a.reason)}</td><td>${btn('details','auditDetail',a.id)}</td></tr>`))+pagination(list.length))}
case 'users':return panel('users',`<p class="notice">${t('permissionHint')}</p>`+table(['username','name','role','warehouse','status','action'],(meta.users||[]).map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.name)}</td><td>${esc(state.customRoles.find(r=>r.id===u.role)?.name||t(u.role==='warehouse'?'warehouseRole':u.role))}</td><td>${u.warehouses.length?u.warehouses.map(w=>esc(name(wget(w)))).join('، '):t('all')}</td><td>${tag(u.active?'active':'disabled')}</td><td>${btn('edit','user',u.id)}</td></tr>`)));
case 'integrations':return integrations();
case 'settings':return settings();
case 'mobile':return `<section class="panel"><div class="toolbar"><input id="scan-input" placeholder="${t('barcode')}" aria-label="${t('barcode')}">${btn('scan','scan')}${btn('scanCamera','camera')}</div><p class="notice">${t('mobileHint')}</p></section><br><div class="phone-grid">${['receive','issue','transfer','count_create'].filter(x=>can(x)).map(x=>`<button data-action="${x}"><span>${x==='receive'?'↙':x==='issue'?'↗':x==='transfer'?'⇄':'▤'}</span>${t(x==='count_create'?'newCount':x)}</button>`).join('')}</div>`;
case 'help':return guide();default:page='dashboard';return dashboard();}}
function reportData(){let headers=[],rows=[];if(filter.report==='summary'){headers=['sku','name','unit','onHand','reserved','available','min','currency','price'];rows=state.products.filter(matches).map(p=>[p.sku,name(p),p.unit,qty(p.id),reserved(p.id),available(state,p.id,filter.warehouse),p.min,p.currency,p.price])}if(filter.report==='movement'){headers=['sku','warehouse','qty','type','lot','serial','at'];rows=filteredMovements().map(m=>[pget(m.product).sku,name(wget(m.warehouse)),m.qty,t(m.type),m.lot,m.serial,m.at])}if(filter.report==='aging'){headers=['sku','warehouse','lot','serial','qty','days'];rows=state.stock.filter(b=>b.qty>0&&matches(pget(b.product))&&(!filter.warehouse||b.warehouse===filter.warehouse)).map(b=>[pget(b.product).sku,name(wget(b.warehouse)),b.lot,b.serial,b.qty,Math.floor((Date.now()-Date.parse(b.receivedAt))/86400000)])}if(filter.report==='dead'){headers=['sku','name','onHand','days'];rows=state.products.filter(matches).filter(p=>qty(p.id)>0).map(p=>{let last=state.movements.filter(m=>m.product===p.id&&m.qty<0&&(!filter.warehouse||m.warehouse===filter.warehouse)).sort((a,b)=>b.at.localeCompare(a.at))[0]?.at||state.stock.filter(b=>b.product===p.id&&b.qty>0).sort((a,b)=>a.receivedAt.localeCompare(b.receivedAt))[0]?.receivedAt;return [p.sku,name(p),qty(p.id),Math.floor((Date.now()-Date.parse(last))/86400000)]}).filter(r=>r[3]>=90)}if(filter.report==='performance'){headers=['warehouse','inbound','outbound','movement'];rows=state.warehouses.filter(w=>!filter.warehouse||w.id===filter.warehouse).map(w=>{let ms=filteredMovements().filter(m=>m.warehouse===w.id);return [name(w),ms.filter(m=>m.qty>0).length,ms.filter(m=>m.qty<0).length,ms.length]})}return {headers,rows}}
function reports(){let {headers,rows}=reportData(),values={};state.stock.filter(b=>b.qty>0&&matches(pget(b.product))&&(!filter.warehouse||b.warehouse===filter.warehouse)).forEach(b=>values[b.costCurrency]=(values[b.costCurrency]||0)+b.qty*b.unitCost);return `<div class="cards">${Object.entries(values).map(([c,v])=>`<article class="card"><h3>${t('stockValue')}</h3><strong>${n(v)} <small>${esc(currency(c))}</small></strong><p>${t('moneyHint')}</p></article>`).join('')}</div><br><section class="panel"><div class="toolbar"><label>${t('savedViews')} <select id="saved-view"><option value="">—</option>${state.savedReports.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></label><label>${t('reportType')} <select id="report-type">${['summary','movement','aging','dead','performance'].map(k=>`<option value="${k}" ${filter.report===k?'selected':''}>${t(k)}</option>`).join('')}</select></label></div>${toolbar(true)}${table(headers,slice(rows).map(r=>`<tr>${r.map((v,i)=>`<td>${headers[i]==='at'?date(v):typeof v==='number'?n(v):esc(unit(currency(v)))}</td>`).join('')}</tr>`))}${pagination(rows.length)}<p class="notice">${t('printHint')}</p></section>`}
function settings(){let row=(title,body,hint='')=>`<div class="setting-row"><div>${t(title)}${hint?`<small>${t(hint)}</small>`:''}</div>${body}</div>`;return `<section class="panel settings">${row('theme',`<select id="theme-setting">${['light','dark','system'].map(k=>`<option value="${k}" ${prefs.theme===k?'selected':''}>${t(k==='system'?'systemTheme':k)}</option>`).join('')}</select>`)}${row('language',btn(prefs.lang==='fa'?'English':'فارسی','lang'))}${row('mode',btn(prefs.mode==='simple'?'pro':'simple','mode'))}${row('calendar',btn(prefs.calendar==='persian'?'Gregorian':'هجری شمسی','calendar'))}${row('timezone',`<select id="timezone">${['Asia/Tehran','Asia/Dubai','Europe/London','America/Los_Angeles','UTC'].map(z=>`<option ${prefs.zone===z?'selected':''}>${z}</option>`).join('')}</select>`)}${row('changePassword',btn('changePassword','password'))}${me.role==='owner'?row('company',btn('edit','company'))+row('system',btn('details','showSystem'),'storageHint')+row('backup',btn('backup','backup')+btn('snapshot','snapshot'),'backupHint')+row('restore',btn('restore','restore'),'restoreHint')+row('activity',btn('verifyAudit','verifyAudit')):''}<p class="notice">${t('dateHint')}</p></section>`}
function integrations(){return panel('apiKey',table(['name','scope','action'],(meta.keys||[]).map(k=>`<tr><td>${esc(k.name)}</td><td>${t(k.scope==='read'?'readOnly':'readWrite')}</td><td>${btn('revoke','revoke',k.id)}</td></tr>`)),btn('newKey','key'))+`<p class="notice" dir="ltr">GET /api/v1/products · /stock · /movements · /orders · POST /api/v1/actions<br>Authorization: Bearer &lt;key&gt; — docs/API.md</p><br>`+panel('integrations',table(['endpoint','status','action'],(meta.hooks?.hooks||[]).map(h=>`<tr><td>${esc(h.url)}</td><td>${tag(h.active?'enabled':'disabled')}</td><td>${h.active?btn('disable','disableHook',h.id):''}</td></tr>`)),btn('newHook','hook'))+`<br>`+panel('deliveries',table(['code','status','qty','note'],(meta.hooks?.deliveries||[]).map(d=>`<tr><td>${esc(d.id.slice(0,8))}</td><td>${tag(d.status)}</td><td>${n(d.attempts)}</td><td>${esc(d.error)}</td></tr>`)))}
function guide(){return panel('help',`<div class="details"><h3>${prefs.lang==='fa'?'شروع کار':'Getting started'}</h3><p>${prefs.lang==='fa'?'برای اجرای پورتابل، فایل Start-MAKAN STOCK.cmd را باز کنید. برای نصب در حساب ویندوز خودتان، Install-MAKAN STOCK.cmd را اجرا کنید. برای توقف از Stop-MAKAN STOCK.cmd استفاده کنید.':'For portable use, open Start-MAKAN STOCK.cmd. To install for your Windows account, run Install-MAKAN STOCK.cmd. Stop with Stop-MAKAN STOCK.cmd.'}</p><div class="actions"><button data-go="system">${t('system')}</button><button data-go="roadmap">${t('roadmap')}</button></div><h3>${t('testGuide')}</h3><ol>${(prefs.lang==='fa'?['کالا ثبت کنید و مقداری ورود بزنید؛ موجودی باید تغییر کند.','برای یک کالا واحد بسته تعریف و نسبت تبدیل آن را ثبت کنید.','سفارش فروش چندقلمی بسازید؛ رزرو، برداشت، بسته‌بندی و ارسال جزئی را بررسی کنید.','برگشت مشتری به قرنطینه می‌رود؛ پس از بررسی از موجودی آزاد کنید.','در یک انبار، ناحیه و قفسه و جایگاه بسازید و موجودی را جابه‌جا کنید.','برای انبار شعبه نقطه سفارش تعریف و هشدار را بررسی کنید.','از اطلاعات پشتیبان بگیرید، سپس توقف و اجرای دوباره را امتحان کنید.']:['Create a product and receive stock.','Define an alternate unit and its conversion factor.','Create a multi-line order and test reservation, picking, packing and partial shipping.','Return shipped stock to quarantine and release after inspection.','Create a zone/rack/bin and move stock between bins.','Set a reorder rule for a branch and check its alert.','Back up your data, then stop and restart.']).map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><p class="notice">${t('source')}</p></div>`)}
function productDetail(id){let p=pget(id);show('details',`<div class="details"><div class="product-hero"><span class="product-icon">${p.image?`<img src="${esc(p.image)}" alt="">`:icon('products')}</span><div><h2>${esc(name(p))}</h2><small>${esc(p.group||p.sku)}</small></div></div><p>${esc(p.description)}</p><div class="custom-fields">${Object.entries(p.attributes).map(([k,v])=>`<span>${esc(k)}: ${esc(v)}</span>`).join('')}</div><dl>${[['sku',p.sku],['barcode',p.barcode],['tracking',t(p.tracking)],['policy',t(p.policy)],['price',n(p.price)+' '+currency(p.currency)],['min',n(p.min)],['target',n(p.target)]].map(([k,v])=>`<dt>${t(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${p.conversions.length?table(['alternateUnit','factor'],p.conversions.map(c=>`<tr><td>${esc(name(state.units.find(u=>u.code===c.unit)))}</td><td>${n(c.factor)} ${esc(unit(p.unit))}</td></tr>`)):''}<div class="actions">${action('edit','product_update',p.id)}${action('conversion','unit_conversion',p.id)}${action('rule','reorder_rule',p.id+'|')}${btn('trace','trace',p.id+'|')}${btn('label','label',p.id)}${p.active?action('archive','product_archive',p.id):action('reactivate','product_reactivate',p.id)}</div><br>${table(['warehouse','onHand','reserved','status','lot','expiry'],state.stock.filter(b=>b.product===p.id&&b.qty>0).map(b=>`<tr><td>${esc(name(wget(b.warehouse)))}</td><td>${n(b.qty)}</td><td>${n(b.reserved)}</td><td>${tag(b.status)}</td><td>${esc(b.lot||b.serial||'—')}</td><td>${date(b.expiry)}</td></tr>`))}</div>`,null,true)}
function orderDetail(id){let o=state.orders.find(x=>x.id===id);let actions=btn('print','print');if(o.status==='backordered')actions+=action('reserveBackorder','order_reserve',o.id,{id:o.id});if(o.kind==='purchase'&&!['received','cancelled'].includes(o.status))actions+=action('confirmReceive','order_receive',o.id,{id:o.id});if(o.status==='reserved')actions+=action('pick','pick',o.id,{id:o.id});if(o.status==='picking')actions+=action('pack','pack',o.id,{id:o.id});if(['packed','part_dispatched','part_returned'].includes(o.status)&&o.lines.some(l=>l.dispatched<l.qty))actions+=action('dispatch','dispatch',o.id,{id:o.id});if(o.kind==='sales'&&o.lines.some(l=>l.dispatched>l.returned))actions+=action('return','return',o.id,{id:o.id});if(!o.lines.some(l=>l.received||l.dispatched)&&o.status!=='cancelled')actions+=action('cancelOrder','order_cancel',o.id,{id:o.id});show('details',`<div class="details"><h2>${esc(o.number)} ${tag(o.status)}</h2><p>${esc(state.contacts.find(c=>c.id===o.contact)?.name)} · ${esc(name(wget(o.warehouse)))} · ${date(o.at)}</p><p>${esc(o.note)}</p><div class="actions">${actions}</div><br>${table(['product','qty','receivedQty','dispatchedQty','returnedQty','price'],o.lines.map(l=>`<tr><td>${productCell(pget(l.product))}</td><td>${n(l.qty)}</td><td>${n(l.received)}</td><td>${n(l.dispatched)}</td><td>${n(l.returned)}</td><td>${n(l.price)} ${esc(currency(l.currency))}</td></tr>`))}${o.packages?.length?`<h3>${prefs.lang==='fa'?'بسته‌ها':'Packages'}</h3><p>${o.packages.map(p=>esc(p.name)+' · '+n(p.weight)+' kg'+(p.items?' · '+p.items.filter(i=>i.qty>0).map(i=>esc(name(pget(o.lines[i.index].product)))+': '+n(i.qty)).join(' / '):'')).join(' / ')}</p>`:''}<h3>${t('pick')}</h3>${table(['product','location','lot','serial','reserved'],o.lines.flatMap(l=>l.allocations.map(x=>`<tr><td>${esc(name(pget(l.product)))}</td><td>${esc(pathName(state,x.location)||'—')}</td><td>${esc(x.lot)}</td><td>${esc(x.serial)}</td><td>${n(x.remaining)}</td></tr>`)))}${o.shipments.map(s=>`<p>${t('dispatch')}: ${date(s.at)} · ${esc(s.carrier)} · ${esc(s.tracking)}</p>`).join('')}</div>`,null,true)}
function label(id){let p=pget(id),value=p.barcode||p.sku;show('label',`<div class="label-preview"><h3>${esc(name(p))}</h3><svg id="barcode-svg"></svg><div id="qr-image"></div><small>${esc(p.sku)}</small></div><div class="form-actions">${btn('print','print')}</div>`);try{JsBarcode('#barcode-svg',value,{format:'CODE128',width:1.4,height:45,fontSize:13,margin:8});let q=qrcode(0,'M');q.addData(value);q.make();$('#qr-image').innerHTML=q.createImgTag(4,6)}catch(e){toast(errorText(e))}}
function trace(arg){let [id,q]=arg.split('|'),rows=state.movements.filter(m=>m.product===id&&(!q||m.lot===q||m.serial===q));show('trace',`<div class="details"><h3>${esc(name(pget(id)))} ${esc(q)}</h3>${table(['warehouse','type','qty','lot','serial','at'],rows.map(m=>`<tr><td>${esc(name(wget(m.warehouse)))}</td><td>${t(m.type)}</td><td>${n(m.qty)}</td><td>${esc(m.lot)}</td><td>${esc(m.serial)}</td><td>${date(m.at)}</td></tr>`))}</div>`,null,true)}
async function camera(){if(!('BarcodeDetector'in window)){toast(t('cameraUnavailable'));return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}})}catch(e){toast(errorText(e));return}let d=show('scan',`<div class="details"><video id="camera-video" autoplay playsinline style="width:100%"></video></div>`),v=$('#camera-video');v.srcObject=stream;let detector=new BarcodeDetector({formats:['code_128','ean_13','qr_code']}),timer=setInterval(async()=>{try{let codes=await detector.detect(v);if(codes.length){filter.search=codes[0].rawValue;close();go('products')}}catch{}},500);const stop=()=>{clearInterval(timer);stream.getTracks().forEach(x=>x.stop())};d.addEventListener('close',stop,{once:true});d.addEventListener('closed',stop,{once:true})}
function scan(){filter.search=$('#scan-input').value.trim();go('products')}
function error(e){toast(errorText(e));if(e.status===401)init()}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-go],[data-action]');if(!el)return;try{if(el.dataset.go){if($('#modal').open)close();return await go(el.dataset.go)}let k=el.dataset.action,arg=el.dataset.arg;if(k==='showSystem')return await go('system');if(k==='theme'){prefs.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';persist();return draw()}if(k==='menu')return $('.sidebar').classList.toggle('open');if(k==='lang'){prefs.lang=prefs.lang==='fa'?'en':'fa';persist();return draw()}if(k==='mode'){prefs.mode=prefs.mode==='simple'?'pro':'simple';persist();return draw()}if(k==='calendar'){prefs.calendar=prefs.calendar==='persian'?'gregory':'persian';persist();return draw()}if(k==='next'||k==='previous'){filter.index+=k==='next'?1:-1;return draw()}if(k==='print')return window.print();if(k==='scan')return scan();if(k==='camera')return camera();if(k==='productDetail')return productDetail(arg);if(k==='orderDetail')return orderDetail(arg);if(k==='label')return label(arg);if(k==='trace')return trace(arg);if(k==='countDetail'){let c=state.counts.find(c=>c.id===arg);return show('details',`<div class="details">${table(['product','expected','counted','difference'],c.lines.map(l=>`<tr><td>${esc(layerName(state.stock.find(b=>b.id===l.layer)))}</td><td>${c.blind&&c.status==='pending'&&!['owner','manager'].includes(me.role)?'—':n(l.expected)}</td><td>${n(l.counted)}</td><td>${c.blind&&c.status==='pending'&&!['owner','manager'].includes(me.role)?'—':n(l.counted-l.expected)}</td></tr>`))}<p>${esc(c.reason)}</p></div>`,null,true)}if(k==='auditDetail'){let a=state.audit.find(x=>x.id===arg);return show('details',`<div class="details"><dl><dt>${t('type')}</dt><dd>${t(a.action)}</dd><dt>${t('name')}</dt><dd>${esc(a.actor)}</dd><dt>${t('at')}</dt><dd>${date(a.at)}</dd><dt>${t('reason')}</dt><dd>${esc(a.reason||'—')}</dd></dl><p class="storage-path">${esc(a.id)}</p></div>`)}

if(k==='pack')return openPremium('packForm',arg,context());if(k==='pick'&&state.orders.find(o=>o.id===arg)?.scanRequired)return openPremium('pickForm',arg,context());if(k==='release')return openPremium('quality_inspect',arg,context());if(['pick','pack','count_approve','reminder_done','notification_read','order_cancel','product_archive','product_reactivate'].includes(k)){if(['order_cancel','product_archive','count_approve'].includes(k)&&!confirm(t('confirm')))return;await mutate({type:k,id:arg});if($('#modal').open)close();return}
if(k==='logout'){if(pending().length&&!confirm(prefs.lang==='fa'?'چند عملیات هنوز در صف آفلاین‌اند. با خروج، صف این حساب در این مرورگر پاک می‌شود. ادامه می‌دهید؟':'There are unapplied offline operations. Signing out clears this account’s local queue. Continue?'))return;clearCache();await api('logout',{});return location.reload()}
if(k==='backup'){let b=await api('backup');return download('MAKAN STOCK-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(b,null,2),'application/json')}
if(k==='snapshot'){let b=await api('snapshot',{});return toast(b.file)}if(k==='verifyAudit'){let v=await api('audit/verify');return toast(v.ok?(prefs.lang==='fa'?'زنجیره فعالیت معتبر است؛ تعداد رویداد: ':'Activity chain valid; events: ')+v.events:JSON.stringify(v))}
if(k==='restore')return chooseFile('.json',async text=>{let backup=JSON.parse(text.replace(/^\uFEFF/,''));show('restore',`<p class="notice full">${t('restoreHint')}</p>${field('password','password')}`,async b=>{await api('restore',{backup,password:b.password});await refresh()})});
if(k==='exportProducts')return download('products.csv',csv([['sku','name','en','category','brand','unit','price','currency','min','target','barcode','tracking','policy'],...state.products.map(p=>[p.sku,p.name,p.en,p.category,p.brand,p.unit,p.price,p.currency,p.min,p.target,p.barcode,p.tracking,p.policy])]),'text/csv');
if(k==='exportReport'){let r=reportData();return download('report-'+filter.report+'.csv',csv([r.headers,...r.rows]),'text/csv')}
if(k==='import_products')return chooseFile('.csv',async text=>{let rows=parseCSV(text),headers=rows.shift();if(!headers.includes('sku')||!headers.includes('name'))throw Error('CSV requires sku and name');let products=rows.map(r=>{let p=Object.fromEntries(headers.map((h,i)=>[h,r[i]]));return {...p,unit:p.unit||'pcs',price:p.price||0,min:p.min||0,target:p.target||p.min||0,currency:p.currency||'IRR',tracking:p.tracking||'none',policy:p.policy||'FIFO'}});show('import',`<p class="notice full">${n(products.length)} ${t('product')} · ${prefs.lang==='fa'?'همه ردیف‌ها با هم ثبت می‌شوند؛ خطا هیچ ردیفی را ثبت نمی‌کند.':'Atomic import: no rows are saved if any row is invalid.'}</p>${table(['sku','name'],products.slice(0,10).map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td></tr>`))}`,()=>mutate({type:'import_products',rows:products}),true)});
if(k==='revoke'){if(confirm(t('confirm'))){await api('keys',{revoke:arg});await refresh()}return}if(k==='disableHook'){if(confirm(t('confirm'))){await api('hooks',{disable:arg});await refresh()}return}
if(openPremium(k,arg,context()))return;if(extraForm(k,arg,context()))return;return openForm(k,arg,context());}catch(e){error(e)}});
window.addEventListener('anbar-prefs',e=>{if(me)api('preferences',e.detail).catch(error)});document.addEventListener('change',e=>{if(e.target.id==='theme-setting'){prefs.theme=e.target.value;persist();draw()}if(e.target.id==='saved-view'){const view=state.savedReports.find(r=>r.id===e.target.value);if(view){Object.assign(filter,view.filters,{index:0});draw()}}if(e.target.id==='timezone'){prefs.zone=e.target.value;persist();draw()}});
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1)||'dashboard';if(p!==page)go(p).catch(error)});
async function auth(setup){document.documentElement.dir=prefs.lang==='fa'?'rtl':'ltr';$('#app').innerHTML=`<form class="login"><img width="48" src="icon.svg" alt="MAKAN STOCK"><h1>${t(setup?'setup':'login')}</h1><p>${t(setup?'setupHint':'localHint')}</p>${setup?`<label>${t('company')}<input name="company" value="ماکان استاک" required></label><label>${t('name')}<input name="name" required></label>`:''}<label>${t('username')}<input name="username" required autocomplete="username" pattern="[a-zA-Z0-9_.-]{3,50}" dir="ltr"></label><label>${t('password')}<input name="password" type="password" minlength="12" required autocomplete="${setup?'new-password':'current-password'}"></label>${setup?`<label class="check-row"><input name="demo" type="checkbox" checked> ${t('demoData')}</label><br>`:''}<button class="primary">${t(setup?'setup':'login')}</button><p class="error" role="alert"></p><button type="button" id="auth-lang" class="subtle">${prefs.lang==='fa'?'English':'فارسی'}</button></form>`;$('#auth-lang').onclick=()=>{prefs.lang=prefs.lang==='fa'?'en':'fa';persist();auth(setup)};$('.login').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('[type=submit]')||e.target.querySelector('.primary');b.disabled=true;try{let data=Object.fromEntries(new FormData(e.target));data.demo=!!data.demo;await api(setup?'setup':'login',data);await init()}catch(err){$('.login .error').textContent=errorText(err)}finally{b.disabled=false}}}
async function init(){try{let health=await api('health');if(health.setup)return auth(true);me=await api('me');state=await api('state');Object.assign(prefs,await api('preferences'));if(!Object.keys(await api('preferences')).length&&!localStorage.getItem('anbar:prefs')){prefs.lang=state.settings.language;prefs.calendar=state.settings.calendar;prefs.zone=state.settings.timezone}saveCache(me,state);await syncQueue();state=await api('state');await loadMeta();draw()}catch(e){if(!e.status&&cached()){let c=cached();me=c.me;state=c.state;connected=false;draw();toast(prefs.lang==='fa'?'نمای آفلاین؛ اطلاعات ممکن است قدیمی باشند.':'Offline view; information may be outdated.');return}if(e.status===401)return auth(false);$('#app').innerHTML=`<div class="login"><h2>${t('offline')}</h2><p>${esc(e.message)}</p><button id="reload">${t('next')}</button></div>`;$('#reload').onclick=init}}
setInterval(clock,30000);setInterval(async()=>{if(!me||$('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;try{let fresh=await api('state');connected=true;const unseen=fresh.notifications.filter(x=>!x.read&&!notificationIds.has(x.id));for(let x of unseen){notificationIds.add(x.id);toast(x.name)}let changed=JSON.stringify(state)!==JSON.stringify(fresh);state=fresh;saveCache(me,state);if(pending().length){await syncQueue();state=await api('state');changed=true}if(changed)draw()}catch{connected=false;let c=$('#connection');if(c){c.textContent=t('offline');c.className='conn offline'}}},15000);
init();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('online',()=>syncQueue().then(refresh).catch(()=>{}));



